local function destroyESP(plr)
	local data = ESPData[plr];
	if not data then
		return;
	end
	for _, obj in pairs(data) do
		if obj.gui then
			pcall(function()
				obj.gui:Destroy();
			end);
		end
		if obj.Remove then
			pcall(function()
				obj:Remove();
			end);
		end
	end
	ESPData[plr] = nil;
end
local function applyESP(plr)
	if (plr == LP) then
		return;
	end
	destroyESP(plr);
	if not State.ESPEnabled then
		return;
	end
	if (Config.ESPTeamCheck and LP.Team and plr.Team and (LP.Team == plr.Team)) then
		return;
	end
	if not plr.Character then
		return;
	end
	local data = {};
	if State.ESPEnabled then
		local h = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\53\15\205\206\229\48\168\19\9", "\123\125\102\170\166\137\89\207"));
		h.Name = "_" .. randomString(8);
		h.FillColor = COLORS.Accent;
		h.OutlineColor = COLORS.Text;
		h.FillTransparency = 0.5;
		h.Adornee = plr.Character;
		h.Parent = ScreenGui;
		data.highlight = h;
	end
	if Config.ESPBox then
		data.box = createBoxESP(plr);
	end
	if Config.ESPName then
		data.name = createNameESP(plr);
	end
	if Config.ESPHealth then
		data.health = createHealthESP(plr);
	end
	if Config.ESPDistance then
		data.distance = createDistanceESP(plr);
	end
	ESPData[plr] = data;
end
local espUpdateConn = nil;
local function updateESP()
	for plr, data in pairs(ESPData) do
		if plr.Character then
			local hum = plr.Character:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\102\21\85\60\0\140\160\74", "\201\46\96\56\93\110\227"));
			local hrp = plr.Character:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\147\22\227\248\27\206\178\7\220\246\26\213\139\2\252\237", "\161\219\99\142\153\117"));
			if (data.health and data.health.fill and hum) then
				local ratio = hum.Health / math.max(hum.MaxHealth, 1);
				data.health.fill.Size = UDim2.fromScale(ratio, 1);
				if (ratio > 0.6) then
					data.health.fill.BackgroundColor3 = COLORS.Green;
				elseif (ratio > 0.3) then
					data.health.fill.BackgroundColor3 = COLORS.Yellow;
				else
					data.health.fill.BackgroundColor3 = COLORS.Red;
				end
			end
			if (data.distance and data.distance.label and hrp) then
				local d = (Camera.CFrame.Position - hrp.Position).Magnitude;
				data.distance.label.Text = math.floor(d) .. "m";
				if (d > Config.ESPMaxDistance) then
					data.distance.gui.Enabled = false;
				else
					data.distance.gui.Enabled = true;
				end
			end
			if (data.name and data.name.label) then
				data.name.label.Text = plr.Name;
			end
		end
	end
end
local function setESP(enabled)
	State.ESPEnabled = enabled;
	if enabled then
		for _, plr in ipairs(Players:GetPlayers()) do
			applyESP(plr);
		end
		if not espUpdateConn then
			espUpdateConn = RunService.RenderStepped:Connect(updateESP);
		end
	else
		for plr, _ in pairs(ESPData) do
			destroyESP(plr);
		end
		ESPData = {};
		if espUpdateConn then
			espUpdateConn:Disconnect();
			espUpdateConn = nil;
		end
	end
end
