local function setFly(enabled)
	State.FlyEnabled = enabled;
	if flyConn then
		flyConn:Disconnect();
		flyConn = nil;
	end
	if not enabled then
		return;
	end
	flyConn = RunService.RenderStepped:Connect(function()
		if not State.FlyEnabled then
			return;
		end
		local char = LP.Character;
		if not char then
			return;
		end
		local hrp = char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\143\3\236\199\247\2\174\18\211\201\246\25\151\23\243\210", "\109\199\118\129\166\153"));
		if not hrp then
			return;
		end
		local move = Vector3.new(0, 0, 0);
		if UserInputService:IsKeyDown(Enum.KeyCode.W) then
			move = move + Camera.CFrame.LookVector;
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.S) then
			move = move - Camera.CFrame.LookVector;
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.A) then
			move = move - Camera.CFrame.RightVector;
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.D) then
			move = move + Camera.CFrame.RightVector;
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
			move = move + Vector3.new(0, 1, 0);
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
			move = move - Vector3.new(0, 1, 0);
		end
		if (move.Magnitude > 0) then
			hrp.AssemblyLinearVelocity = move.Unit * Config.FlySpeed;
		else
			hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		end
	end);
end
